def bal(t):
    return tuple(t.count(a) - t.count(b) for a, b in ('()', '[]', '{}'))

ok = True
before = bal(src)
for name, old, new in edits:
    n = src.count(old)
    if n == 1:
        src = src.replace(old, new); print('✔', name)
    else:
        ok = False; print('❌', name, '(못 찾음)' if n == 0 else f'({n}곳)')
if ok and bal(src) != before:
    ok = False; print('❌ 괄호 짝이 안 맞아요')

if os.path.exists(NEW) and open(NEW, encoding='utf-8').read().replace('\r\n', '\n') != NEW_FILE:
    print('❌ lib/widgets/artist_info_sheet.dart 가 이미 있는데 내용이 달라요 (지우고 다시 돌려 주세요)'); ok = False

if not ok:
    print('\n하나라도 실패해서 저장 안 했어요.'); sys.exit(1)

os.makedirs(os.path.dirname(NEW), exist_ok=True)
open(NEW, 'wb').write((NEW_FILE.replace('\n', '\r\n') if crlf else NEW_FILE).encode('utf-8'))
print('✔ 새 파일 만듦:', NEW)
out = src.replace('\n', '\r\n') if crlf else src
open(PLAYER, 'wb').write(out.encode('utf-8'))
print('\n저장했어요:', PLAYER)
